using CipherCapsule.Builder;
using System.Text.Json;
using System.Diagnostics;
var results=new List<object>();int passed=0,failed=0;string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);
void Assert(bool ok){if(!ok)throw new Exception("Assertion failed");}
async Task Test(string name,Func<Task> action){try{await action();passed++;results.Add(new{name,passed=true});}catch(Exception e){failed++;results.Add(new{name,passed=false,error=e.GetType().Name+": "+e.Message});}Console.WriteLine(name);}
await Test("old unbounded semaphore mechanism reproduced without GUI",async()=>{using var gate=new SemaphoreSlim(1);var release=new TaskCompletionSource();async Task Old(){await gate.WaitAsync();try{await release.Task;}finally{gate.Release();}}var first=Old();var second=Old();await Task.Delay(20);Assert(!first.IsCompleted&&!second.IsCompleted);release.SetResult();await Task.WhenAll(first,second);});
await Test("visual to code preserves unsaved HTML",async()=>{var f=new Fixture();await f.Queue.Request(1);Assert(f.Current==1&&f.Code==f.Visual&&!f.Busy);});
await Test("code to visual preserves unsaved source",async()=>{var f=new Fixture{Current=1,Code="<p>new 日本語 😀</p>"};await f.Queue.Request(0);Assert(f.Current==0&&f.Visual==f.Code);});
await Test("last click on current visual cancels pending code request",async()=>{var f=new Fixture();var gate=new TaskCompletionSource<EditorSwitchDraft>();f.Preparation=(_,_)=>gate.Task;var first=f.Queue.Request(1);var last=f.Queue.Request(0);await last.WaitAsync(TimeSpan.FromSeconds(1));gate.SetResult(new(true,"STALE"));await Task.Delay(10);Assert(f.Current==0&&f.Visual==Fixture.Html&&f.Code=="old source"&&!f.Busy);});
await Test("obsolete failure cannot overwrite the last request",async()=>{var f=new Fixture();var gate=new TaskCompletionSource<EditorSwitchDraft>();f.Preparation=(_,_)=>gate.Task;var first=f.Queue.Request(1);await f.Queue.Request(0);gate.SetException(new IOException("sensitive html must not be logged"));await Task.Delay(10);Assert(f.Errors.Count==0&&f.Current==0);});
await Test("same target coalesces instead of repeated execution",async()=>{var f=new Fixture();var gate=new TaskCompletionSource<EditorSwitchDraft>();int calls=0;f.Preparation=(_,_)=>{calls++;return gate.Task;};var a=f.Queue.Request(1);var b=f.Queue.Request(1);Assert(ReferenceEquals(a,b));gate.SetResult(new(true,Fixture.Html));await a;Assert(calls==1&&f.Current==1);});
await Test("timeout releases state and late reply cannot commit",async()=>{var f=new Fixture(TimeSpan.FromMilliseconds(40));var gate=new TaskCompletionSource<EditorSwitchDraft>();f.Preparation=(_,_)=>gate.Task;await f.Queue.Request(1).WaitAsync(TimeSpan.FromSeconds(1));Assert(f.Current==0&&f.Code=="old source"&&!f.Busy&&f.Errors.Single() is TimeoutException);gate.SetResult(new(true,"LATE"));await Task.Delay(10);Assert(f.Current==0&&f.Code=="old source");});
await Test("timeout allows explicit retry without application restart",async()=>{var f=new Fixture(TimeSpan.FromMilliseconds(40));f.Preparation=(_,_)=>new TaskCompletionSource<EditorSwitchDraft>().Task;await f.Queue.Request(1);f.Preparation=null;await f.Queue.Request(1);Assert(f.Current==1&&f.Code==Fixture.Html&&!f.Busy);});
await Test("script exception preserves both buffers and permits retry",async()=>{var f=new Fixture();f.Preparation=(_,_)=>throw new IOException("private body");await f.Queue.Request(1);Assert(f.Current==0&&f.Visual==Fixture.Html&&f.Code=="old source"&&!f.Busy);f.Preparation=null;await f.Queue.Request(1);Assert(f.Current==1);});
await Test("explicit sanitation refusal keeps code authoritative",async()=>{var f=new Fixture{Current=1,Code="<script>not allowed</script>"};f.Preparation=(_,_)=>Task.FromResult(new EditorSwitchDraft(false,""));await f.Queue.Request(0);Assert(f.Current==1&&f.Code=="<script>not allowed</script>"&&!f.Busy);});
await Test("commit failure releases queue and leaves contents unchanged",async()=>{var f=new Fixture();f.FailCommit=true;await f.Queue.Request(1);Assert(f.Current==0&&f.Code=="old source"&&!f.Busy);f.FailCommit=false;await f.Queue.Request(1);Assert(f.Current==1);});
await Test("close cancels a never completing operation",async()=>{var f=new Fixture();f.Preparation=(_,_)=>new TaskCompletionSource<EditorSwitchDraft>().Task;var task=f.Queue.Request(1);f.Queue.Stop();await task.WaitAsync(TimeSpan.FromSeconds(1));Assert(f.Current==0&&!f.Busy);await f.Queue.Request(1);Assert(f.Current==0);});
await Test("24 alternating switches retain code visual equality",async()=>{var f=new Fixture();for(int i=0;i<24;i++)await f.Queue.Request(i%2==0?1:0);Assert(f.Visual==Fixture.Html&&f.Code==Fixture.Html&&f.Current==0&&!f.Busy);});
foreach(int size in new[]{9,12,17})await Test($"{size}pt metadata change does not participate in content transitions",async()=>{var f=new Fixture();f.Font=size;await f.Queue.Request(1);f.Font=12;await f.Queue.Request(0);Assert(f.Visual==Fixture.Html&&f.Code==Fixture.Html);});
await Test("trace retains only metadata, never exception message or HTML",async()=>{var f=new Fixture();f.Preparation=(_,_)=>throw new IOException("SECRET_HTML_PAYLOAD");await f.Queue.Request(1);var json=JsonSerializer.Serialize(f.Trace);Assert(!json.Contains("SECRET_HTML_PAYLOAD")&&!json.Contains(Fixture.Html)&&json.Contains("IOException"));});
await Test("empty valid HTML is not confused with transport failure",async()=>{var f=new Fixture{Visual=""};await f.Queue.Request(1);Assert(f.Current==1&&f.Code=="");});
foreach(float size in new[]{9f,12f,17f})await Test($"existing INI {size}pt save restore",()=>{var settings=new Settings{Font=size,OutputFormat=OutputFormat.CCAP,PasswordRevealed=true};settings.Save();var loaded=Settings.Load();Assert(loaded.Font==size&&loaded.OutputFormat==OutputFormat.CCAP&&loaded.PasswordRevealed);return Task.CompletedTask;});
await Test("INI never persists password or HTML",()=>{var text=File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"CipherCapsule.ini"));Assert(!text.Contains(Fixture.Html)&&!text.Contains("Password=")&&text.Contains("PasswordRevealed="));return Task.CompletedTask;});
File.WriteAllText(Path.Combine(root,"results.json"),JsonSerializer.Serialize(new{passed,failed,desktop_input=false,real_gui_verified=false,tests=results},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"{passed} passed / {failed} failed");return failed==0?0:1;

sealed class Fixture
{
    public const string Html="<p style=\"font-size:18pt\">未保存 日本語 😀 <strong>太字</strong></p>";
    public int Current,Font=12;public string Visual=Html,Code="old source";public bool Busy,FailCommit;public List<Exception> Errors=[];public List<EditorSwitchTrace> Trace=[];
    public Func<int,CancellationToken,Task<EditorSwitchDraft>>? Preparation;
    public EditorSwitchQueue Queue{get;}
    public Fixture(TimeSpan? timeout=null){Queue=new(()=>Current,async(target,ct)=>Preparation!=null?await Preparation(target,ct):new(true,target==1?Visual:Code),(target,draft)=>{if(FailCommit)throw new IOException("commit");if(target==1)Code=draft.Html;else Visual=draft.Html;Current=target;},value=>Busy=value,error=>Errors.Add(error),value=>Trace.Add(value),timeout);}
}
